/// Map a Windows time zone key name (as reported by
/// GetDynamicTimeZoneInformation's TimeZoneKeyName) to its IANA
/// equivalent, e.g. "Pacific Standard Time" -> "America/Los_Angeles".
pub fn windowsToIana(windows_name: []const u8) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = mappings.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, mappings[mid].windows, windows_name)) {
            .lt => lo = mid + 1,
            .gt => hi = mid,
            .eq => return mappings[mid].iana,
        }
    }
    return null;
}

